 beam(k,a,c,r=.035,tint=1,n=8){const va=new THREE.Vector3(...a),vb=new THREE.Vector3(...c),v=vb.clone().sub(va);if(v.length()<.001)return;const g=new THREE.CylinderGeometry(r,r,v.length(),n),m=new THREE.Matrix4().compose(va.add(vb).multiplyScalar(.5),new THREE.Quaternion().setFromUnitVectors(UP,v.normalize()),new THREE.Vector3(1,1,1));this.geom(k,g,m,tint);g.dispose();}
 finish(group,resources,textures){for(const[key,a]of this.parts){const[component,period,kind]=key.split('|'),def=DEFS[kind],mat=new THREE.MeshStandardMaterial({color:def.color,roughness:def.roughness,metalness:def.metalness||0,map:def.map?textures[def.map]:null,vertexColors:true,side:THREE.DoubleSide,transparent:!!def.opacity,opacity:def.opacity??1,depthWrite:!def.opacity});if(def.map&&kind!=='paving'){mat.bumpMap=textures[def.map];mat.bumpScale=kind==='ashlar'?.045:kind==='stone'||kind==='rubble'?.028:.012;}const g=new THREE.BufferGeometry();for(const[n,arr,size]of[['position',a.p,3],['normal',a.n,3],['uv',a.u,2],['color',a.c,3]])g.setAttribute(n,new THREE.Float32BufferAttribute(arr,size));g.computeBoundingBox();g.computeBoundingSphere();const mesh=new THREE.Mesh(g,mat);mesh.name='Salvador · '+component+' · '+kind;mesh.castShadow=kind!=='glass';mesh.receiveShadow=true;mesh.userData={salvadorFabric:true,component,period,materialKind:kind,baseColor:mat.color.clone(),baseMap:mat.map,baseBumpMap:mat.bumpMap};group.add(mesh);resources.materials.push(mat);resources.geometries.push(g);}this.cube.dispose();}
